<details>
<summary>Exact standalone probe source</summary>

Saved under `.local/150702-final-effect-proof.mts` in the reviewed checkout and run through the repository's `scripts/tsx.mjs` loader, once per named case in a fresh process. The output argument is a task-owned result file. No production source changes were required.

```typescript
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import fs from "node:fs/promises";
import path from "node:path";
import {
  prepareAgentRunAdmission,
  createOperationalRunInstanceRef,
  resolveAdmittedRunActiveAssertion,
} from "../src/agents/admitted-run-context.js";
import {
  buildCurrentRunRestartRecoveryClaim,
  bindCommandHarnessCompletionAssertion,
} from "../src/agents/agent-command-restart-recovery.js";
import { deliverAgentCommandResult } from "../src/agents/command/delivery.js";
import { prepareCommandSessionRecoveryEntry } from "../src/agents/command/session-preparation.js";
import { recoverRestartAbortedMainSessions } from "../src/agents/main-session-recovery/main-session-restart-recovery.js";
import { persistPendingFinalDeliveryMarker } from "../src/agents/pending-final-delivery-marker.js";
import { createMessageReceiptFromOutboundResults } from "../src/channels/message/receipt.js";
import type { ChannelPlugin } from "../src/channels/plugins/types.public.js";
import {
  appendTranscriptMessage,
  loadExactSessionEntry,
  replaceSessionEntry,
} from "../src/config/sessions/session-accessor.js";
import type { GatewayRecoveryRuntime } from "../src/gateway/server-instance-runtime.types.js";
import type { AgentRunRequest } from "../src/gateway/server-methods/agent-request-types.js";
import { loadDeliveryQueueEntries } from "../src/infra/delivery-queue-sqlite.js";
import { OUTBOUND_DELIVERY_QUEUE_NAME } from "../src/infra/outbound/delivery-queue-media-staging.js";
import { createAgentHarnessTaskRuntime } from "../src/plugin-sdk/agent-harness-task-runtime.js";
import { resetGlobalHookRunner } from "../src/plugins/hook-runner-global.js";
import { resetPluginRuntimeStateForTest, setActivePluginRegistry } from "../src/plugins/runtime.js";
import { captureOpenClawStateWorkerContext } from "../src/state/openclaw-state-worker-context.js";
import { captureHarnessCompletionRecovery } from "../src/tasks/agent-harness-completion-recovery.js";
import { createAgentHarnessTaskRuntimeScope } from "../src/tasks/agent-harness-task-runtime-scope.js";
import { updateTask } from "../src/tasks/task-registry-mutation.js";
import { reloadTaskRegistryFromStoreAsync } from "../src/tasks/task-registry-state.js";
import { getTaskById, markTaskTerminalById } from "../src/tasks/task-registry.js";
import { stopTaskRegistryMaintenance } from "../src/tasks/task-registry.maintenance.js";
import { createOutboundTestPlugin, createTestRegistry } from "../src/test-utils/channel-plugins.js";
import { withOpenClawTestState } from "../src/test-utils/openclaw-test-state.js";
import { cleanupSessionStateForTest } from "../src/test-utils/session-state-cleanup.js";
import { createDeferred } from "../test/helpers/promise.js";

const head = execFileSync("git", ["rev-parse", "HEAD"], { encoding: "utf8" }).trim();
assert.equal(head, "71bebdd1a4090c88b2f5eb525a880d522529c0a5");
const results: unknown[] = [];
const started = performance.now();
for (const scenario of ["allowed", "cancelled", "reassigned", "saved-delegated"] as const) {
  if (scenario !== process.argv[3]) continue;
  const caseStarted = performance.now();
  await withOpenClawTestState(
    { scenario: "minimal", label: `recovery-final-${scenario}` },
    async (state) => {
      const key = "agent:main:matrix:direct:proof";
      const child = "proof:child";
      const source = "announce:proof:child:succeeded";
      const target = {
        agentId: "main",
        sessionKey: key,
        storePath: path.join(state.sessionsDir(), "sessions.json"),
      };
      const route = { channel: "matrix", to: "!proof:example", accountId: "default" };
      const entry = {
        sessionId: "proof-parent",
        lifecycleRevision: "proof-revision",
        status: "running" as const,
        abortedLastRun: true,
        updatedAt: Date.now(),
        permissionMode: "guarded" as const,
      };
      const tasks = createAgentHarnessTaskRuntime({
        runtime: "subagent",
        taskKind: "generic-proof",
        scope: createAgentHarnessTaskRuntimeScope({ requesterSessionKey: key }),
        runIdPrefix: "proof:",
      });
      const task = tasks.createRunningTaskRun({
        runId: child,
        sourceId: child,
        task: "Synthetic completion",
        requesterAgentId: "main",
        notifyPolicy: "silent",
      });
      tasks.finalizeTaskRunByRunId({
        runId: child,
        status: "succeeded",
        endedAt: Date.now(),
        terminalSummary: "Synthetic result",
      });
      tasks.setDetachedTaskDeliveryStatusByRunId({ runId: child, deliveryStatus: "pending" });
      const provenance = {
        kind: "inter_session",
        sourceTool: scenario === "saved-delegated" ? "sessions_send" : "agent_harness_task",
        sourceChannel: "internal",
        sourceSessionKey: child,
      };
      const claim =
        scenario === "saved-delegated"
          ? undefined
          : captureHarnessCompletionRecovery({
              agentId: "main",
              sessionKey: key,
              entry,
              runId: source,
              inputProvenance: provenance,
            });
      if (scenario !== "saved-delegated") assert.ok(claim);
      const persisted = {
        ...entry,
        ...buildCurrentRunRestartRecoveryClaim({
          entry,
          runId: source,
          sourceRunId: source,
          sourceIngress: "internal",
          sourceReplyDeliveryMode: "automatic",
          deliveryContext: route,
          harnessCompletion: claim,
        }),
        ...(scenario === "saved-delegated"
          ? {
              pendingFinalDelivery: {
                kind: "replayable" as const,
                text: "Unsent delegated final",
                createdAt: Date.now(),
                intentId: "old-unowned-final",
                deliveries: [{ id: "old-unowned-delivery", state: "prepared" as const }],
              },
            }
          : {}),
      };
      await replaceSessionEntry(target, persisted);
      await appendTranscriptMessage(
        { ...target, sessionId: entry.sessionId },
        {
          message: {
            role: "user",
            content: "Saved interrupted input",
            idempotencyKey: `${source}:user`,
            provenance,
            __openclaw: { runId: source },
          },
        },
      );
      // Reopen saved SQLite state, rather than lending the producer's live handles to recovery.
      await cleanupSessionStateForTest({ stateDir: state.stateDir });
      await reloadTaskRegistryFromStoreAsync(captureOpenClawStateWorkerContext());
      const effectPath = state.path("final-effect.txt");
      const noticePath = state.path("notice.txt");
      const trace: string[] = ["saved-state-reopened"];
      const entered = createDeferred();
      const release = createDeferred();
      const adopted = createDeferred();
      let dispatches = 0;
      let terminalStatus: "ok" | "error" | undefined;
      let deliveryStatus: unknown;
      let receiver: Promise<{ runId: string; status: "ok" | "error" }> | undefined;
      const plugin: ChannelPlugin = {
        ...createOutboundTestPlugin({
          id: "matrix",
          outbound: {
            deliveryMode: "direct",
            sendText: async () => {
              throw new Error("message adapter owns final I/O");
            },
          },
        }),
        message: {
          id: "matrix",
          durableFinal: { capabilities: { text: true } },
          send: {
            lifecycle: {
              beforeSendAttempt: async () => {
                trace.push("delivery-preparation-entered");
                entered.resolve();
                await release.promise;
              },
            },
            text: async ({ text, onPlatformSendDispatch, assertDirectAdapterHandoff }) => {
              trace.push("platform-handoff-entered");
              await onPlatformSendDispatch?.();
              assertDirectAdapterHandoff?.();
              await fs.appendFile(effectPath, `${text}\n`, "utf8");
              trace.push("physical-final-written");
              return {
                messageId: "proof-final",
                receipt: createMessageReceiptFromOutboundResults({
                  results: [{ channel: "matrix", messageId: "proof-final" }],
                  kind: "text",
                }),
              };
            },
          },
        },
      };
      setActivePluginRegistry(createTestRegistry([{ pluginId: "matrix", source: "test", plugin }]));
      const runReceiver = async (
        request: AgentRunRequest,
        options?: Parameters<GatewayRecoveryRuntime["dispatchAgent"]>[2],
      ) => {
        dispatches++;
        trace.push("recovery-dispatched");
        const runId = String(request.idempotencyKey);
        const current = loadExactSessionEntry(target)?.entry;
        assert.ok(current);
        const opts = {
          message: String(request.message),
          deliver: true,
          replyChannel: "matrix",
          replyTo: route.to,
          accountId: route.accountId,
          sessionKey: key,
          runId,
          inputProvenance: request.inputProvenance,
        };
        const prepared = prepareCommandSessionRecoveryEntry({
          entry: current,
          sessionId: entry.sessionId,
          sessionKey: key,
          runId,
          agentId: "main",
          opts,
          deliveryContext: route,
          now: Date.now(),
          isSessionRollover: false,
        });
        const bound = bindCommandHarnessCompletionAssertion({
          claim: prepared.guardedHarnessCompletion,
          persisted: current,
          sessionKey: key,
          storePath: target.storePath,
          opts,
        });
        await appendTranscriptMessage(
          { ...target, sessionId: entry.sessionId },
          {
            message: {
              role: "user",
              content: opts.message,
              idempotencyKey: `${runId}:user`,
              provenance: request.inputProvenance,
              __openclaw: { runId },
            },
          },
        );
        const admission = prepareAgentRunAdmission({
          cfg: {},
          facts: {
            agentId: "main",
            runId,
            ingress: { kind: "system", boundary: "isolated-recovery-receiver", state: "present" },
          },
          operationalRunInstance: createOperationalRunInstanceRef(runId),
          assertSourceCurrent: bound.assertSourceCurrent,
        });
        try {
          const context = await admission.admit("embedded");
          const expiresAtMs = Date.now() + 60_000;
          options?.onStartOwner?.({
            observe: () => ({ executionStarted: true, expiresAtMs }),
            abort: () => false,
          });
          options?.onAccepted?.({ runId, status: "accepted" });
          options?.onExecutionStarted?.();
          await adopted.promise;
          const running = loadExactSessionEntry(target)?.entry;
          assert.ok(running);
          assert.equal(running.abortedLastRun, false);
          trace.push("recovery-adoption-committed");
          const assertCurrent = resolveAdmittedRunActiveAssertion(context);
          assert.ok(assertCurrent);
          const payloads = [{ text: "Synthetic completed result" }];
          const marker = await persistPendingFinalDeliveryMarker({
            agentId: "main",
            deliver: true,
            sessionStore: { [key]: running },
            sessionKey: key,
            sessionEntry: running,
            storePath: target.storePath,
            suppressVisibleSessionEffects: false,
            sessionReboundDuringRun: false,
            payloads,
            deliveryContext: route,
            runOwnedSessionId: entry.sessionId,
          });
          assert.equal(marker.pendingFinalDeliveryMarkerPersisted, true);
          const delivered = await deliverAgentCommandResult({
            cfg: {},
            deps: {},
            runtime: { log: () => {}, error: () => {}, exit: () => {} },
            opts: bound,
            outboundSession: { agentId: "main", key },
            sessionEntry: marker.sessionEntry,
            result: { meta: { durationMs: 1 } },
            payloads,
            assertDeliveryCurrent: assertCurrent,
          });
          deliveryStatus = delivered.deliveryStatus;
          terminalStatus = "ok";
        } catch (error) {
          trace.push("delivery-rejected");
          console.error("Receiver failure:", error);
          deliveryStatus = { error: error instanceof Error ? error.name : "unknown" };
          terminalStatus = "error";
        } finally {
          admission.close();
        }
        return { runId, status: terminalStatus };
      };
      const gateway: GatewayRecoveryRuntime = {
        dispatchAgent: <T,>(
          request: AgentRunRequest,
          _timeout?: number,
          options?: Parameters<GatewayRecoveryRuntime["dispatchAgent"]>[2],
        ) => {
          receiver = runReceiver(request, options);
          return receiver as Promise<T>;
        },
        dispatchSessionMethod: async () => {
          throw new Error("unexpected session RPC");
        },
        waitForAgent: async <T,>() =>
          (terminalStatus
            ? { status: terminalStatus, endedAt: Date.now() }
            : { status: "timeout" }) as T,
        sendRecoveryNotice: async (notice) => {
          if (notice.isCurrent && !notice.isCurrent({})) return { suppressed: true };
          await fs.appendFile(noticePath, `${notice.text}\n`, "utf8");
          return { suppressed: false };
        },
      };
      const recovering = recoverRestartAbortedMainSessions({
        cfg: {},
        stateDir: state.stateDir,
        gatewayRuntime: gateway,
      });
      try {
        const recovery = await recovering;
        if (scenario !== "saved-delegated") {
          assert.equal(recovery.started, 1);
          adopted.resolve();
          await Promise.race([
            entered.promise,
            receiver!.then(() => {
              throw new Error(
                `receiver ended before final-send preparation: ${JSON.stringify({ trace, deliveryStatus })}`,
              );
            }),
          ]);
          await assert.rejects(fs.stat(effectPath), { code: "ENOENT" });
          if (scenario === "cancelled") {
            markTaskTerminalById({
              taskId: task.taskId,
              status: "cancelled",
              endedAt: Date.now() + 1,
            });
            assert.equal(getTaskById(task.taskId)?.status, "cancelled");
            trace.push("task-cancelled-after-dispatch");
          } else if (scenario === "reassigned") {
            updateTask(task.taskId, { requesterSessionKey: "agent:main:replacement" });
            assert.equal(getTaskById(task.taskId)?.requesterSessionKey, "agent:main:replacement");
            trace.push("task-reassigned-after-dispatch");
          }
          release.resolve();
        }
        await receiver;
        const effects = await fs.readFile(effectPath, "utf8").catch((error) => {
          if (error.code === "ENOENT") return "";
          throw error;
        });
        const notices = await fs.readFile(noticePath, "utf8").catch((error) => {
          if (error.code === "ENOENT") return "";
          throw error;
        });
        assert.equal(effects, scenario === "allowed" ? "Synthetic completed result\n" : "");
        assert.equal(dispatches, scenario === "saved-delegated" ? 0 : 1);
        assert.deepEqual(
          loadDeliveryQueueEntries(OUTBOUND_DELIVERY_QUEUE_NAME, state.stateDir),
          [],
        );
        if (scenario === "saved-delegated") {
          assert.ok(loadExactSessionEntry(target)?.entry.mainRestartRecovery?.tombstone);
          assert.match(notices, /\/new or \/reset/);
          await recoverRestartAbortedMainSessions({
            cfg: {},
            stateDir: state.stateDir,
            gatewayRuntime: gateway,
          });
          assert.equal(dispatches, 0);
          assert.equal(await fs.readFile(noticePath, "utf8"), notices);
        }
        results.push({
          scenario,
          recovery,
          dispatches,
          physicalFinalWrites: effects ? 1 : 0,
          actionableNotice: /\/new or \/reset/.test(notices),
          deliveryStatus,
          taskStatus: getTaskById(task.taskId)?.status,
          taskDelivery: getTaskById(task.taskId)?.deliveryStatus,
          pendingQueueEntries: 0,
          trace,
          elapsedMs: Math.round(performance.now() - caseStarted),
        });
      } finally {
        adopted.resolve();
        release.resolve();
        await receiver?.catch(() => {});
        resetGlobalHookRunner();
        resetPluginRuntimeStateForTest();
        await stopTaskRegistryMaintenance();
      }
    },
  );
}
assert.equal(execFileSync("git", ["rev-parse", "HEAD"], { encoding: "utf8" }).trim(), head);
const report = {
  head,
  scope:
    "Production recovery, generic admitted source/custody and automatic delivery owners; synthetic model output and a task-local filesystem transport, no external service.",
  node: process.version,
  cases: results,
  elapsedMs: Math.round(performance.now() - started),
  cleanup: "fixture-owned state and workers joined and removed",
};
await fs.writeFile(process.argv[2], `${JSON.stringify(report, null, 2)}\n`);
console.log(JSON.stringify(report, null, 2));

```
